{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled for the S3 bucket. Without versioning, data recovery in case of accidental deletion or overwrites is not possible."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket. Without logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled with a KMS key. This could lead to unencrypted data being stored in the bucket, increasing the risk of data breaches."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "data" {
  bucket        = "${local.resource_prefix.value}-data"
  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-data"
    Environment = local.resource_prefix.value
  }, {})
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "data" {
  bucket = aws_s3_bucket.data.id
  target_bucket = "${local.resource_prefix.value}-logs"
  target_prefix = "${local.resource_prefix.value}/data/"
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = "arn:aws:kms:region:account-id:key/key-id"
      sse_algorithm     = "aws:kms"
    }
  }
}",
  "fix_summary": "Enabled versioning for data recovery, added access logging for monitoring, configured a Public Access block to prevent accidental public exposure, and enforced server-side encryption with KMS for data protection."
}
